/**
 * Чат «поставить задачу ИИ своими словами». Владелец пишет, чего хочет («увеличить продажи, не меняя карточки»), ИИ при необходимости задаёт уточняющие вопросы
 * (ограничения, допустимая маржа, сроки, что можно трогать), затем выбирает товары и по каждому составляет план в той же гибкой форме, что и решения по сигналам алгоритмов:
 * шаги по дням, контрольные точки, критерии успеха и ограничители. Каждый план после принятия ведётся программой и показывает «было → стало».
 * Скорость без потери качества: выбор товаров (быстрый вызов) и планы по каждому товару (параллельные вызовы, у каждого сфокусированный контекст), потом параллельная проверка вторым ИИ.
 * Ограничения владельца из диалога обязательны для ИИ. Деньги не трогаются: числа цены считает программа, подтверждает человек.
 */

export const CHAT_PROTOCOL_VERSION = "c3";
/** Сколько раундов уточняющих вопросов допускается до составления плана. */
export const MAX_QUESTION_ROUNDS = 2;
/** Потолок числа товаров, по которым ИИ составляет планы за один раз (сколько именно, определяет область задачи). */
export const MAX_PLAN_PRODUCTS = 6;

/** Готовые элементы интерфейса в ответе агента. Строятся из данных кабинета: ИИ называет только идентификаторы, а сервер их проверяет. */
export type ChatBlock =
  | { type: "products"; title: string; nmIds: string[] }
  | { type: "product"; nmId: string }
  | { type: "task"; nmId: string | null; title: string; taskId?: string; category?: string }
  | { type: "tasks"; title: string; items: Array<{ id: string; nmId: string | null; title: string; severity: "critical" | "important" | "opportunity"; category: string }>; total: number }
  | { type: "article"; id: string; title: string; summary: string; branch: "wb" | "karto" }
  | { type: "events"; days: 7 | 14 | 30; group?: string }
  | { type: "info"; kind: "reviews" | "promos" | "supplies" }
  | { type: "action"; action: AgentAction; /** Заголовок, факты («Было → Станет») и последствия от проверяющей программы. */ title?: string; facts?: string[]; effect?: string; risk?: "low" | "medium" | "high" }
  | { type: "price_edit"; nmId: string; field: "discount" | "price"; value: number | null; /** Изменение цены в процентах («подними на 3%»): клиент считает новую цену от текущей. */ pct?: number | null }
  | { type: "analytics"; view: "trend" | "summary" | "funnel" | "products" | "money" | "stock" | "ads" | "market"; days: 7 | 14 | 28 | 60 | 90; nmId?: string; part?: AnalyticsPartId }
  | { type: "section"; id: string; title: string; note: string }
  /** Поручение на будущее или регулярное: показывается карточкой, создаётся после подтверждения владельцем. */
  | { type: "order"; input: OrderInput; /** Если задан, карточка не создаёт новое поручение, а обновляет существующее. */ replaceId?: string };

export type ChatMessage = { role: "user" | "assistant"; text: string; at: string; /** Варианты быстрых ответов к каждому вопросу (параллельно questions). */ questionOptions?: string[][]; /** Страницы, по которым подготовлен ответ из интернета. */ sources?: Array<{ title: string; url: string }>; questions?: string[]; suggestions?: string[]; blocks?: ChatBlock[]; /** Планы, составленные именно в этом ответе (идентификаторы находок): карточки показываются под ним, а не внизу диалога. */ planIds?: string[] };

