export type ChatTaskRef = { id: string; nmId: string | null; title: string; severity: "critical" | "important" | "opportunity"; category: string };

export type AnalyticsPartId = "orders" | "sum" | "weekdays" | "low" | "over" | "worst";
const PARTS = ["orders", "sum", "weekdays", "low", "over", "worst"] as const;
export const EVENT_GROUPS = ["sales", "stock", "price", "content", "reviews", "orders", "ads", "money", "news"];
export const ANALYTICS_VIEWS = ["trend", "summary", "funnel", "products", "money", "stock", "ads", "market"] as const;
type AnalyticsViewId = (typeof ANALYTICS_VIEWS)[number];

/** Ближайший допустимый период раздела «Аналитика»: 7, 14, 28, 60 или 90 дней. */
export function snapDays(raw: unknown): 7 | 14 | 28 | 60 | 90 {
  const n = typeof raw === "number" && Number.isFinite(raw) ? raw : 28;
  const options = [7, 14, 28, 60, 90] as const;
  return options.reduce((best, d) => (Math.abs(d - n) < Math.abs(best - n) ? d : best), 28 as 7 | 14 | 28 | 60 | 90);
}

export type ChatBlocksContext = {
  /** Идентификаторы уже созданных поручений: по ним агент может изменить существующее. */
  orderIds?: string[];
  /** Последняя реплика владельца: по ней список выбора дополняется всеми товарами с такими же словами в названии. */
  ownerText?: string;
  products: ChatProduct[];
  /** Открытые сигналы алгоритмов по товарам (названия). */
  tasksByNm: Map<string, string[]>;
  /** Открытые задачи магазина целиком: из них собирается блок «Задачи» и ссылка на конкретную задачу. */
  taskList?: ChatTaskRef[];
  /** Рекламные кампании магазина: из них проверяются действия с рекламой. */
  campaigns?: ChatCampaign[];
  /** Действие программы по товару (карточка, акции, реклама, характеристики): проверяется и собирается сервером по данным товара. */
  resolveDo?: (spec: { nmId: string; action: unknown }) => Extract<ChatBlock, { type: "action" }> | null;
  /** Статья базы знаний по id: название и краткое содержание, либо null. */
  kb: (id: string) => { title: string; summary: string; branch: "wb" | "karto" } | null;
};

const normTitle = (s: string) => s.toLowerCase().replace(/ё/g, "е").replace(/(\d)\s+(л|шт|мл|кг|г|см|мм)(?![а-я])/g, "$1$2");
const titleWords = (s: string) => normTitle(s).split(/[^a-zа-я0-9]+/).filter((w) => w.length >= 2);

/**
 * Товары, в названии которых есть все значимые слова запроса (по основе слова: «ведра», «ведро» совпадают).
 * Значимыми считаются только слова, которые вообще встречаются в названиях товаров магазина: «скидка», «сколько», «осталось» отсеиваются сами.
 */
export function productsMatching(ownerText: string, products: ChatProduct[]): string[] {
  const stem = (w: string) => (/\d/.test(w) || w.length <= 4 ? w : w.slice(0, Math.min(7, w.length - 1)));
  const titles = products.map((p) => ({ nmId: p.nmId, words: new Set(titleWords(p.title).map(stem)) }));
  const inAny = new Set(titles.flatMap((t) => [...t.words]));
  const words = [...new Set(titleWords(ownerText).map(stem))].filter((w) => inAny.has(w));
  if (words.length === 0) return [];
  return titles.filter((t) => words.every((w) => t.words.has(w))).map((t) => t.nmId);
}

/** Блоки ответа: только то, что можно проверить по данным кабинета и базе знаний. Не больше двух; неизвестные товары, задачи и статьи отбрасываются. */
/** Время суток, которое названо словами: «утром» это 6–10, «вечером» 18–21 и так далее. Быстрые ответы предлагают самые частые часы. */
export function timeOptions(ownerText: string): string[] {
  const t = ownerText.toLowerCase();
  if (/утр/.test(t)) return ["06:00", "07:00", "08:00", "09:00", "10:00"];
  if (/обед|полдень/.test(t)) return ["12:00", "13:00", "14:00"];
  if (/днём|днем|после обеда/.test(t)) return ["13:00", "14:00", "15:00", "16:00"];
  if (/вечер/.test(t)) return ["18:00", "19:00", "20:00", "21:00"];
  if (/ноч/.test(t)) return ["00:00", "01:00", "02:00", "03:00"];
  return ["09:00", "12:00", "15:00", "18:00", "21:00"];
}

/**
 * Быстрые ответы на вопросы про время и срок поручения подбираем сами по словам владельца, а не доверяем случайным вариантам модели.
 * Остальные вопросы остаются как есть.
 */
export function smartOrderOptions(questions: string[], options: string[][] | undefined, ownerText: string): string[][] | undefined {
  const isTime = (q: string) => /(во сколько|в какое время|какое время|точное время|в котором часу|в какой час)/i.test(q);
  const isDuration = (q: string) => /(сколько дней|на сколько дней|как долго|на какой срок|какой срок|сколько раз)/i.test(q);
  if (!questions.some((q) => isTime(q) || isDuration(q))) return options;
  return questions.map((q, i) => (isTime(q) ? timeOptions(ownerText) : isDuration(q) ? ["7 дней", "14 дней", "30 дней", "Пока не остановлю"] : options?.[i] ?? []));
}

/**
 * Поручение без названного владельцем времени или срока не создаём: вместо карточки задаём уточняющие вопросы.
 * Время нужно «каждый день» и «по дням недели» (и разовому), срок нужен любому регулярному поручению. Подтверждает их модель полем confirmed.
 */
export function orderGaps(raw: string): { questions: string[]; options: string[][] } | null {
  const json = extractJson(raw) as { blocks?: unknown } | null;
  if (!json || !Array.isArray(json.blocks)) return null;
  const item = (json.blocks as Array<Record<string, unknown>>).find((b) => b && b.type === "order");
  if (!item) return null;
  const sched = (item.schedule ?? {}) as Record<string, unknown>;
  const type = sched.type;
  const confirmed = Array.isArray(item.confirmed) ? (item.confirmed as unknown[]).map(String) : [];
  const timeless = type === "every" || (type === "check" && item.kind !== "when_orders");
  const needsTime = !timeless && type !== "check" && !confirmed.includes("time");
  const recurring = type !== "once";
  const hasEnd = Boolean(sched.until) || sched.durationDays != null || sched.maxRuns != null;
  const needsDuration = recurring && !hasEnd && !confirmed.includes("duration");
  const questions: string[] = [];
  const options: string[][] = [];
  if (needsTime) {
    questions.push("Во сколько по Москве это должно происходить?");
    options.push(["08:00", "09:00", "12:00", "18:00"]);
  }
  if (needsDuration) {
    questions.push("На сколько дней поручение должно работать?");
    options.push(["7 дней", "14 дней", "30 дней", "Пока не остановлю"]);
  }
  return questions.length > 0 ? { questions, options } : null;
}

export function parseChatBlocks(raw: string, ctx: ChatBlocksContext): ChatBlock[] {
  const json = extractJson(raw) as { blocks?: unknown } | null;
  if (!json || !Array.isArray(json.blocks)) return [];
  const known = new Set(ctx.products.map((p) => p.nmId));
  const out: ChatBlock[] = [];
  for (const item of json.blocks) {
    if (out.length >= 2) break;
    const b = item as { type?: unknown; title?: unknown; nmIds?: unknown; nmId?: unknown; id?: unknown; severity?: unknown; view?: unknown; days?: unknown; field?: unknown; value?: unknown; part?: unknown; group?: unknown; kind?: unknown };
    const nm = typeof b.nmId === "string" ? b.nmId : typeof b.nmId === "number" ? String(b.nmId) : "";
    if (b.type === "products" && Array.isArray(b.nmIds)) {
      const ids = [...new Set(b.nmIds.map((x) => (typeof x === "number" ? String(x) : typeof x === "string" ? x : "")).filter((x) => known.has(x)))].slice(0, 8);
      // Модель иногда называет лишь часть подходящих товаров: добавляем все, чьё название содержит слова владельца (до 12), её выбор идёт первым.
      const matched = ctx.ownerText ? productsMatching(ctx.ownerText, ctx.products) : [];
      if (matched.length >= 2) for (const id of matched) if (!ids.includes(id) && ids.length < 12) ids.push(id);
      if (ids.length > 0) out.push({ type: "products", title: typeof b.title === "string" && b.title.trim() ? b.title.trim().slice(0, 90) : "Какой товар вы имеете в виду?", nmIds: ids });
    } else if (b.type === "product" && known.has(nm)) {
      if (!out.some((o) => o.type === "product" && o.nmId === nm)) out.push({ type: "product", nmId: nm });
    } else if (b.type === "task" && typeof b.title === "string") {
      const title = b.title.trim();
      const owner = known.has(nm) ? nm : null;
      if (owner && (ctx.tasksByNm.get(owner) ?? []).includes(title)) {
        const ref = (ctx.taskList ?? []).find((t) => t.nmId === owner && t.title === title);
        out.push({ type: "task", nmId: owner, title, ...(ref ? { taskId: ref.id, category: ref.category } : {}) });
      }
    } else if (b.type === "tasks") {
      const only = typeof b.severity === "string" ? b.severity : "all";
      const rank = { critical: 0, important: 1, opportunity: 2 } as const;
      let list = (ctx.taskList ?? []).filter((t) => (known.has(nm) ? t.nmId === nm : true) && (only === "critical" ? t.severity === "critical" : true));
      list = list.slice().sort((a, c) => rank[a.severity] - rank[c.severity]);
      if (list.length > 0 && !out.some((o) => o.type === "tasks")) {
        out.push({ type: "tasks", title: typeof b.title === "string" && b.title.trim() ? b.title.trim().slice(0, 90) : only === "critical" ? "Критичные задачи" : "Задачи", items: list.slice(0, 5), total: list.length });
      }
    } else if (b.type === "article" && typeof b.id === "string") {
      const a = ctx.kb(b.id);
      if (a) out.push({ type: "article", id: b.id, title: a.title, summary: a.summary, branch: a.branch });
    } else if (b.type === "info" && (b.kind === "reviews" || b.kind === "promos" || b.kind === "supplies")) {
      if (!out.some((o) => o.type === "info" && o.kind === b.kind)) out.push({ type: "info", kind: b.kind });
    } else if (b.type === "do" && ctx.resolveDo && known.has(nm)) {
      const done = ctx.resolveDo({ nmId: nm, action: (item as { action?: unknown }).action });
      if (done && !out.some((o) => o.type === "action")) out.push(done);
    } else if (b.type === "ads_action") {
      const action = buildChatAction(item as ChatActionSpec, ctx);
      if (action && !out.some((o) => o.type === "action")) out.push({ type: "action", action });
    } else if (b.type === "order") {
      // Поручение: проверяем теми же правилами, что и форму; кампания и товары только из данных магазина.
      const checked = validateOrderInput({ ...(item as Record<string, unknown>), createdFrom: "chat" });
      const gaps = orderGaps(JSON.stringify({ blocks: [item] }));
      if (checked.ok && !gaps && !out.some((o) => o.type === "order")) {
        const p = checked.value.params as { campaignId?: string; nmIds?: string[] };
        const needsCampaign = checked.value.kind === "ads_deposit" || (checked.value.kind === "when_orders" && (checked.value.params as { then?: string }).then === "deposit");
        const campaignOk = !needsCampaign || (ctx.campaigns ?? []).some((c) => c.id === p.campaignId);
        const productsOk = checked.value.kind !== "price_step" || (p.nmIds ?? []).every((id) => known.has(id));
        const replaceId = typeof (item as { replaceId?: unknown }).replaceId === "string" && (ctx.orderIds ?? []).includes((item as { replaceId: string }).replaceId) ? (item as { replaceId: string }).replaceId : undefined;
        if (campaignOk && productsOk) out.push({ type: "order", input: checked.value, ...(replaceId ? { replaceId } : {}) });
      }
    } else if (b.type === "events") {
      const d = typeof b.days === "number" && b.days > 14 ? 30 : typeof b.days === "number" && b.days > 7 ? 14 : 7;
      if (!out.some((o) => o.type === "events")) out.push({ type: "events", days: d, ...(typeof b.group === "string" && EVENT_GROUPS.includes(b.group) ? { group: b.group } : {}) });
    } else if (b.type === "price_edit" && known.has(nm) && (b.field === "discount" || b.field === "price")) {
      const v = typeof b.value === "number" && Number.isFinite(b.value) ? b.value : null;
      if (!out.some((o) => o.type === "price_edit")) out.push({ type: "price_edit", nmId: nm, field: b.field, value: v, ...(typeof (item as { pct?: unknown }).pct === "number" ? { pct: (item as { pct: number }).pct } : {}) });
    } else if (b.type === "analytics" && typeof b.view === "string" && (ANALYTICS_VIEWS as readonly string[]).includes(b.view)) {
      if (!out.some((o) => o.type === "analytics")) out.push({ type: "analytics", view: b.view as AnalyticsViewId, days: snapDays(b.days), ...(known.has(nm) ? { nmId: nm } : {}), ...(typeof b.part === "string" && (PARTS as readonly string[]).includes(b.part) ? { part: b.part as AnalyticsPartId } : {}) });
    } else if (b.type === "section" && typeof b.id === "string" && CHAT_SECTIONS[b.id]) {
      if (!out.some((o) => o.type === "section" && o.id === b.id)) out.push({ type: "section", id: b.id, title: CHAT_SECTIONS[b.id]!.title, note: CHAT_SECTIONS[b.id]!.note });
    }
  }
  return out;
}

/**
 * Вопрос про цену, скидку или остаток называет товар или группу товаров, а модель не показала карточку: добавляем сами.
 * Один подходящий товар даёт строку с ценой и остатком, несколько дают список всех вариантов. Числа берутся из кабинета на экране.
 */
export function ensureProductBlocks(blocks: ChatBlock[], ownerText: string, products: ChatProduct[]): ChatBlock[] {
  if (blocks.some((b) => b.type === "product" || b.type === "products")) return blocks;
  if (!/(цен[ауые]?(?![а-я])|скидк|остат|сколько стоит|в наличии|сколько осталось|сколько штук)/i.test(ownerText.toLowerCase())) return blocks;
  const ids = productsMatching(ownerText, products);
  if (ids.length === 1) return [{ type: "product", nmId: ids[0]! } as ChatBlock, ...blocks].slice(0, 2);
  if (ids.length >= 2) return [{ type: "products", title: "Все подходящие товары", nmIds: ids.slice(0, 12) } as ChatBlock, ...blocks].slice(0, 2);
  return blocks;
}

/**
 * Быстрые ответы на уточняющий вопрос агента: варианты из «A или B» и «Да»/«Нет» для вопросов, на которые так и отвечают.
 * Для вопросов с открытым ответом («сколько», «какой», «почему») кнопок нет: владелец отвечает словами.
 */
export function quickAnswers(question: string): string[] {
  const q = question.trim().replace(/\s+/g, " ");
  if (!q.includes("?")) return [];
  const sentences = q.split("?").map((x) => x.trim()).filter(Boolean);
  const cap = (x: string) => x.charAt(0).toUpperCase() + x.slice(1);
  for (const sentence of sentences) {
    const parts = sentence.split(/\s+или\s+/i);
    if (parts.length !== 2) continue;
    const left = parts[0]!.split(" ").filter(Boolean);
    const right = parts[1]!.split(" ").filter(Boolean);
    if (left.length === 0 || right.length === 0) continue;
    // Варианты только короткие: «Поднять или снизить», «Фото или текст». Длинные обороты кнопками не разбираем.
    if (left.length > 2 || right.length > 6) continue;
    const n = left.length;
    const a = left.slice(-n).join(" ").replace(/[,:;]+$/, "");
    const b = right.slice(0, n).join(" ").replace(/[,:;.]+$/, "");
    if (a && b && a.toLowerCase() !== b.toLowerCase()) return [cap(a), cap(b)];
  }
  if (sentences.length !== 1) return [];
  const open = /(^|[\s,(])(какой|какая|какое|какие|каких|какую|какому|каким|какими|какого|сколько|где|когда|почему|зачем|кто|куда|откуда|чем|что именно|как именно|на сколько|насколько|в какой|за какой|до какого)(?![а-я])/i;
  if (open.test(sentences[0]!)) return [];
  return ["Да", "Нет"];
}

/**
 * Когда есть готовые блоки, текст ответа остаётся короткой подводкой: списки и пересказ цифр из блока убираем.
 */
export function leadText(text: string): string {
  const lines = text.split(/\r?\n/);
  const out: string[] = [];
  for (const l of lines) {
    if (/^\s*([-•*]|\d+[.)])\s+/.test(l)) break;
    out.push(l);
  }
  const lead = out.join("\n").trim();
  if (!lead) return "Вот что есть в кабинете:";
  const kept = lead.split(/\n\s*\n/).slice(0, 3).join("\n\n").trim();
  return kept.length > 1200 ? `${kept.slice(0, 1200).replace(/\s+\S*$/, "")}…` : kept;
}

/**
 * Вопрос про данные магазина на любом языке: по смыслу слов выбираем экран «Аналитики» и период, если модель его не показала.
 * Экран живой: его можно наводить, раскрывать и сортировать прямо в чате.
 */
export function ensureAnalyticsBlocks(blocks: ChatBlock[], ownerText: string, products: ChatProduct[]): ChatBlock[] {
  if (blocks.some((b) => b.type === "analytics")) return blocks;
  const t = ownerText.toLowerCase().replace(/ё/g, "е");
  if (/(постав|созда|добав|составь|удали|измени|поменя|отредакт|пополни|останови|запусти|включи|выключи|подними|повысь|понизь|снизь|убери)/.test(t)) return blocks;
  // Просьба посоветовать или решить проблему («как увеличить конверсию», «что делать с ДРР») — это разговор и план, а не вывод данных.
  if (/(как (мне |нам )?(увелич|повыс|улучш|подня|снизи|сниж|исправ|сдела|уменьш|ускор|настро)|что делать|посоветуй|помоги|подскажи как|стоит ли|нужно ли)/.test(t)) return blocks;
  // Без явной просьбы показать данные подсказка по словам молчит: уместность графика решает модель.
  if (!/(покаж|дай |выведи|нарисуй|открой|хочу (увидеть|посмотреть)|график|диаграмм|воронк|динамик|сводк|в штуках|по дням)/.test(t)) return blocks;
  const has = (re: RegExp) => re.test(t);
  let view: AnalyticsViewId | null = null;
  if (has(/(воронк|просмотр|в корзин|конверси|карточк.*(не )?конверт)/)) view = "funnel";
  else if (has(/(куда (уход|девает|тратит)|прибыл|маржинальн|удержан|себестоимост|чист[а-я]+ выручк|расход[а-я]* на wb|структур[а-я]* выручк)/)) view = "money";
  else if (has(/(реклам|дрр|кампани|кпд|рекламн|ставк[а-я]* (по|в) реклам)/)) view = "ads";
  else if (has(/(остатк|хватит|запас|оборачиваем|излишек|дефицит|закончит|на склад)/) && !has(/(задач|сигнал)/)) view = "stock";
  else if (has(/(рынок|категори[а-я]* (wb|вайлдб)|конкурент|спрос в категори)/)) view = "market";
  else if (has(/(график|динамик|по дням|как менял|тренд|продаж[а-я]* (за|в штук)|заказ[а-я]* (за|по дням)|в штуках)/)) view = "trend";
  else if (has(/(средний чек|выкуп|сводк|итог|как дела|общ[а-я]+ картин|как у нас|как торгуем|показател|кратк[а-я]+ анализ|анализ магазин|что с магазином)/)) view = "summary";
  else if (has(/(топ товар|лучш[а-я]+ товар|худш[а-я]+ товар|abc|рейтинг товар|матриц|какие товары (лучше|хуже|продаются|не продаются|просел|упал|падают|тянут)|по каждому товару)/)) view = "products";
  if (!view) return blocks;
  const ids = productsMatching(ownerText, products);
  const part: AnalyticsPartId | undefined =
    view === "trend" || view === "summary"
      ? has(/(дням недели|день недели|по дням нед|будн|выходн)/) ? "weekdays" : has(/(сумм|выручк|оборот|в рублях|в деньгах)/) ? "sum" : "orders"
      : view === "stock" ? (has(/(излишек|залежал|много запаса|переизбыток|затовар)/) ? "over" : "low")
      : view === "products" ? (has(/(худш|падени|просел|упал|теряют)/) ? "worst" : "orders")
      : undefined;
  // Вопрос про конкретный товар, а экран у «Аналитики» общий по магазину: без «Товаров» и «Сводки» его не подставляем.
  if (ids.length > 0 && view !== "summary" && view !== "products" && view !== "money") return blocks;
  const nmId = ids.length === 1 && (view === "summary" || view === "products" || view === "money") ? ids[0] : undefined;
  if (nmId) view = "products";
  const m = t.match(/(\d+)\s*(дн|нед|месяц)/);
  const raw = /месяц/.test(t) ? 30 : m ? (m[2] === "нед" ? Number(m[1]) * 7 : m[2] === "месяц" ? 30 : Number(m[1])) : /недел/.test(t) ? 7 : /квартал|3 месяц/.test(t) ? 90 : view === "summary" ? 7 : 28;
  return [{ type: "analytics", view, days: snapDays(raw), ...(nmId ? { nmId } : {}), ...(part ? { part } : {}) } as ChatBlock, ...blocks.filter((b) => b.type !== "product" && b.type !== "products" && b.type !== "section")].slice(0, 2);
}

/**
 * Владелец просит показать задачи («какие задачи по ведру», «покажи критичные»), а модель блок не показала: собираем сами из настоящих задач.
 * Товары берутся по словам из названия, «критичные» оставляют только критичные. Просьба «все задачи» без уточнения ведёт в раздел «Задачи».
 */
export function ensureTaskBlocks(blocks: ChatBlock[], ownerText: string, products: ChatProduct[], taskList: ChatTaskRef[]): ChatBlock[] {
  if (blocks.some((b) => b.type === "tasks")) return blocks;
  const t = ownerText.toLowerCase();
  if (!/(задач|сигнал)/.test(t) || !/(покаж|какие|какая|есть|список|что по|критич|важн|срочн|посмотр|открой)/.test(t)) return blocks;
  if (/(постав|созда|добав|составь|сделай|оформи|удали|измени)/.test(t)) return blocks;
  const critical = /критич|срочн/.test(t);
  const matched = productsMatching(ownerText, products);
  if (matched.length === 0 && !critical) {
    const sec = CHAT_SECTIONS["tasks"];
    if (sec) return [{ type: "section", id: "tasks", title: sec.title, note: sec.note } as ChatBlock, ...blocks.filter((b) => b.type !== "task" && b.type !== "section")].slice(0, 2);
    return blocks;
  }
  const rank = { critical: 0, important: 1, opportunity: 2 } as const;
  const scoped = taskList.filter((x) => (matched.length > 0 ? x.nmId != null && matched.includes(x.nmId) : true));
  const onlyCritical = scoped.filter((x) => x.severity === "critical");
  // Критичных нет: честно говорим об этом и показываем остальные задачи, а не молчим.
  const noCritical = critical && onlyCritical.length === 0;
  const list = (critical && !noCritical ? onlyCritical : scoped).slice().sort((a, b) => rank[a.severity] - rank[b.severity]);
  if (list.length === 0) return blocks;
  const where = matched.length === 1 ? " по товару" : matched.length > 1 ? " по найденным товарам" : "";
  const title = noCritical ? `Критичных задач нет, вот остальные${where}` : (critical ? "Критичные задачи" : "Задачи") + where;
  return [{ type: "tasks", title, items: list.slice(0, 5), total: list.length } as ChatBlock, ...blocks.filter((b) => b.type !== "task" && b.type !== "product" && b.type !== "products")].slice(0, 2);
}

/**
 * Просьба поменять скидку или цену товара («поменяй скидку с -2 до 0», «подними цену ведра 12л»): показываем строку товара с полем и подтверждением.
 * Товар берётся из «nm …» в последнем сообщении (выбор из списка) или по названию; число из слов «до N» / «на N». Само изменение идёт только после нажатия «Подтвердить».
 */
export function ensurePriceEditBlocks(blocks: ChatBlock[], recentOwner: string[], products: ChatProduct[]): ChatBlock[] {
  // Просьба с расписанием или несколькими шагами («каждые 3 дня», «первое… второе… если не поможет») это поручение или план, а не разовая правка цены.
  const lastRaw = (recentOwner[recentOwner.length - 1] ?? "").toLowerCase().replace(/ё/g, "е");
  if (/(кажд(ый|ые|ую|ое|ых)\s|ежедневн|раз в \d|по (пн|вт|ср|чт|пт|сб|вс)|первое|второе|третье|если (это |и это )?не поможет|через \d+ дн|в течение \d+)/.test(lastRaw)) return blocks.filter((x) => x.type !== "price_edit");
  if (blocks.some((b) => b.type === "price_edit")) {
    // Модель назвала товар, но не число: «подними на 3%» берём из слов владельца.
    const lastText = (recentOwner[recentOwner.length - 1] ?? "").toLowerCase().replace(/ё/g, "е");
    const pm = lastText.match(/(?:на|в)\s*(\d{1,2}(?:[.,]\d)?)\s*%/);
    const pctFromText = pm ? (/(сниз|уменьш|дешевл|убав)/.test(lastText) ? -1 : 1) * Number(pm[1]!.replace(",", ".")) : null;
    return blocks
      .filter((x) => x.type !== "product" && x.type !== "products")
      .map((x) => (x.type === "price_edit" && x.field === "price" && x.value == null && x.pct == null && pctFromText != null ? { ...x, pct: pctFromText } : x));
  }
  const joined = recentOwner.join(" \n ").toLowerCase().replace(/ё/g, "е");
  const last = (recentOwner[recentOwner.length - 1] ?? "").toLowerCase().replace(/ё/g, "е");
  if (!/(скидк|цен[уыае]?(?![а-я])|стоимост)/.test(joined)) return blocks;
  if (/клуб/.test(last)) return blocks;
  const verbs = /(поменя|измени|смени|постав|установ|сделай|повыс|подними|сниз|уменьш|увелич|убери|верни)/;
  // Намерение должно быть в последней реплике; из прежних берём только товар и число, когда владелец выбрал товар из списка («nm …»).
  if (!verbs.test(last) && !(/nm\s*\d{6,}/.test(last) && verbs.test(joined))) return blocks;
  if (/(составь план|план по|задач[уи] )/.test(last)) return blocks;
  const known = new Set(products.map((p) => p.nmId));
  const nmM = last.match(/nm\s*(\d{6,})/) ?? joined.match(/nm\s*(\d{6,})/);
  let nmId: string | null = nmM && known.has(nmM[1]!) ? nmM[1]! : null;
  if (!nmId) {
    const a = productsMatching(last, products);
    const b = productsMatching(joined, products);
    nmId = a.length === 1 ? a[0]! : b.length === 1 ? b[0]! : null;
  }
  if (!nmId) return blocks;
  const field: "discount" | "price" = /скидк/.test(joined) ? "discount" : "price";
  let value: number | null = null;
  const m = field === "discount" ? joined.match(/до\s*(-?\d{1,2})(?!\d)/) ?? joined.match(/(?:на|в)\s*(\d{1,2})\s*%/) : joined.match(/(?:до|на)\s*(\d[\d\s]{1,8})\s*(?:₽|руб|р\b)/);
  if (m) value = Number(m[1]!.replace(/\s/g, ""));
  let pctChange: number | null = null;
  if (field === "price" && value == null) {
    const pm = last.match(/(?:на|в)\s*(\d{1,2}(?:[.,]\d)?)\s*%/) ?? joined.match(/(?:на|в)\s*(\d{1,2}(?:[.,]\d)?)\s*%/);
    if (pm) pctChange = (/(сниз|уменьш|дешевл|убав)/.test(last) ? -1 : 1) * Number(pm[1]!.replace(",", "."));
  }
  if (value != null && !(field === "discount" ? value >= 0 && value <= 99 : value > 0)) value = null;
  return [{ type: "price_edit", nmId, field, value, ...(pctChange != null ? { pct: pctChange } : {}) } as ChatBlock, ...blocks.filter((b) => b.type !== "product" && b.type !== "products")].slice(0, 2);
}

/** Статья базы знаний уместна только при вопросе о правилах WB; рядом с цифрами, задачами и графиками она лишняя. */
export function filterArticleBlocks(blocks: ChatBlock[], ownerText: string): ChatBlock[] {
  if (!blocks.some((b) => b.type === "article")) return blocks;
  const t = ownerText.toLowerCase();
  const asksRules = /(правил|как (работает|считает|устроен|начисл|рассчит)|что такое|что значит|объясни|почему wb|комисси|штраф|регламент|термин|как (подключ|настро|измен|созда)|инструкц|справк|статья)/.test(t);
  const hasData = blocks.some((b) => b.type === "analytics" || b.type === "tasks" || b.type === "product" || b.type === "products" || b.type === "price_edit");
  return asksRules && !hasData ? blocks : blocks.filter((b) => b.type !== "article");
}

/** Подсказки следующих шагов под блоком, если модель их не дала: по смыслу показанного. */
export function defaultSuggestions(blocks: ChatBlock[]): string[] {
  const a = blocks.find((b) => b.type === "analytics") as Extract<ChatBlock, { type: "analytics" }> | undefined;
  if (a) {
    const by: Record<string, string[]> = {
      trend: ["Покажи заказы по дням недели", "Покажи воронку", "Куда уходит выручка?"],
      summary: ["Покажи воронку", "Куда уходит выручка?", "Покажи остатки"],
      funnel: ["Покажи динамику заказов", "Какие товары теряют покупателей?"],
      money: ["Покажи динамику заказов", "Покажи рекламу"],
      stock: ["Покажи задачи по излишку запаса", "Покажи динамику заказов"],
      ads: ["Покажи динамику заказов", "Куда уходит выручка?"],
      products: ["Покажи воронку", "Покажи задачи по магазину"],
      market: ["Покажи динамику заказов", "Покажи воронку"],
    };
    if (a.view === "trend" && a.part === "weekdays") return ["Покажи динамику заказов", "Покажи воронку", "Куда уходит выручка?"];
    return by[a.view] ?? [];
  }
  if (blocks.some((b) => b.type === "events")) return ["Покажи динамику заказов", "Какие есть задачи по магазину?", "Покажи рекламу"];
  if (blocks.some((b) => b.type === "tasks")) return ["Составь план по этим задачам", "Покажи динамику заказов"];
  return [];
}

/** Просьба показать новости или события: настоящая лента из «Событий» за период и по теме. */
export function ensureEventsBlocks(blocks: ChatBlock[], ownerText: string): ChatBlock[] {
  if (blocks.some((b) => b.type === "events")) return blocks;
  const t = ownerText.toLowerCase().replace(/ё/g, "е");
  if (!/(новост|событи|что нового|что произошло|что случилось|что изменилось|лента|уведомлен|что у меня нового)/.test(t)) return blocks;
  if (/(постав|созда|добав|составь|удали)/.test(t)) return blocks;
  const m = t.match(/(\d+)\s*(дн|нед|месяц)/);
  const raw = /месяц/.test(t) ? 30 : m ? (m[2] === "нед" ? Number(m[1]) * 7 : Number(m[1])) : /недел/.test(t) ? 7 : /сегодня|вчера|сутки/.test(t) ? 7 : 7;
  const days: 7 | 14 | 30 = raw > 14 ? 30 : raw > 7 ? 14 : 7;
  const group = /(реклам)/.test(t) ? "ads" : /(отзыв|вопрос)/.test(t) ? "reviews" : /(остатк|склад)/.test(t) ? "stock" : /(цен|скидк|акци)/.test(t) ? "price" : /(новост.*(wb|вайлдб|площадк|маркетплейс))/.test(t) ? "news" : undefined;
  return [{ type: "events", days, ...(group ? { group } : {}) } as ChatBlock, ...blocks.filter((b) => b.type !== "article" && b.type !== "section")].slice(0, 2);
}

/** Второй шаг для вопросов, которым нужны сведения из интернета: ответ по найденным страницам, с честной оговоркой, если нашлось мало. */
export const CHAT_WEB_SYSTEM = `Ты ИИ-менеджер продавца на Wildberries. Владелец задал вопрос, которому нужны свежие сведения из интернета. Тебе доступны результаты веб-поиска.
Правила:
- Ответь по существу на русском: коротко, структурно, с выделением **жирным** главных фактов. Списки строками с «- », шаги «1. ». Без заголовков с # и таблиц.
- Опирайся на найденные страницы. Если источники расходятся или данных мало, прямо скажи это. Ничего не выдумывай, даты и числа бери из источников.
- Если владелец просит «кратко», «простыми словами» или спрашивает, что значит термин, дай определение и один короткий пример, до 600 символов, без разбора источников. Цифры магазина добавляй, только если вопрос про его магазин.
- Если вопрос касается магазина владельца, а в данных ниже есть нужные цифры, свяжи ответ с ними; цифры магазина бери только из данных.
- ПЕРСОНАЛИЗАЦИЯ. После общего ответа на развёрнутый вопрос («как маркировать товар», «как отгрузить заказ», «что такое ДРР») добавь отдельным коротким абзацем «Для вашего магазина:» (1–3 предложения) и примени ответ к реальным товарам и цифрам из данных ниже: назови конкретные товары по названию (например, строительные вёдра), скажи, чем для них это важно или удобно, что сделать в первую очередь. Только то, что действительно следует из данных и меняет практический совет; не выдумывай свойства товаров. Если связи с магазином нет, абзац не пиши. Связывай по смыслу вопроса, а не по тому, что под рукой: для вопроса про маркировку, упаковку или карточку важны вид товара (металл, пластик, размеры, комплекты, штуки в упаковке), его название и категория; остатки, заказы и скорость продаж упоминай, только если вопрос про них или они прямо меняют совет. Один-два самых подходящих товара, не перечисляй каталог. Для короткого определения («что такое CTR») персонализация не нужна.
- Не называй адреса сайтов в тексте: источники показываются отдельно.
- Термины и аббревиатуры расшифровывай только как в источниках или так: ДРР — доля рекламных расходов, CTR — доля кликов от показов. Если не уверен, не расшифровывай.
ФОРМАТ. Только JSON без текста вокруг: {"reply":"...","suggestions":["..."]}. suggestions от нуля до трёх коротких следующих шагов от лица владельца.`;

/** В тексте ответа из интернета адреса не нужны (источники показываются отдельно): убираем ссылки, пустые скобки и лишние пробелы. */
/** Технические имена полей (snake_case) не должны попадать к владельцу: убираем скобки и слова с такими именами. */
export function scrubInternal(text: string): string {
  return text
    .replace(/\s*\([^()]*[a-z]+(?:_[a-z0-9]+)+[^()]*\)/g, "")
    .replace(/(?<![A-Za-z0-9_])[a-z]+(?:_[a-z0-9]+)+(?:\s*=\s*[\d.,]+)?/g, "")
    .replace(/[ 	]{2,}/g, " ");
}

export function stripLinks(text: string): string {
  return scrubInternal(text)
    // Разметка цитат от поискового плагина: оставляем только текст внутри.
    .replace(/<\/?cite[^>]*>/gi, "")
    .replace(/\[([^\]]+)\]\((?:https?:\/\/)[^)]*\)/g, "$1")
    .replace(/\(\s*(?:https?:\/\/[^\s)]+\s*[;,]?\s*)+\)/g, "")
    .replace(/https?:\/\/\S+/g, "")
    .replace(/\(\s*\)/g, "")
    .replace(/[ 	]+([.,;:])/g, "$1")
    .replace(/[ 	]{2,}/g, " ")
    .trim();
}

export type ChatActionSpec = { op?: unknown; campaignId?: unknown; nmId?: unknown; bidRub?: unknown; limitRub?: unknown; sumRub?: unknown; clubPercent?: unknown };

const str = (v: unknown): string => (typeof v === "string" ? v.trim() : typeof v === "number" && Number.isFinite(v) ? String(v) : "");
const num = (v: unknown): number | null => {
  const n = typeof v === "number" ? v : typeof v === "string" ? Number(v.replace(",", ".").replace(/\s/g, "")) : NaN;
  return Number.isFinite(n) ? n : null;
};

/**
 * Действие в рекламе или скидке Клуба из просьбы владельца. Модель называет только идентификаторы и числа; кампания, товар и прежние значения
 * берутся из данных кабинета, а числа проверяются по границам WB. Возвращает null, если чего-то не хватает или значение недопустимо.
 */
export function buildChatAction(spec: ChatActionSpec, ctx: Pick<ChatBlocksContext, "products" | "campaigns">): AgentAction | null {
  const campaigns = ctx.campaigns ?? [];
  const campaign = campaigns.find((c) => c.id === str(spec.campaignId));
  const product = ctx.products.find((p) => p.nmId === str(spec.nmId));
  const op = str(spec.op);
  if (op === "pause" || op === "resume") return campaign ? { type: op, campaignId: campaign.id } : null;
  if (op === "deposit") {
    const sum = num(spec.sumRub);
    return campaign && sum != null && (DEPOSIT_STEPS as readonly number[]).includes(sum) ? { type: "deposit", campaignId: campaign.id, sumRub: sum } : null;
  }
  if (op === "bid") {
    const bid = num(spec.bidRub);
    if (!campaign || !product || bid == null || bid <= 0 || bid > 5000) return null;
    const current = campaign.bids.find((b) => b.nmId === product.nmId);
    if (!current) return null;
    return { type: "bid", advertId: campaign.id, nmId: product.nmId, bidRub: Math.round(bid * 100) / 100, previousBidRub: current.searchRub };
  }
  if (op === "daily_limit") {
    const limit = num(spec.limitRub);
    if (!campaign || limit == null) return null;
    const prev = campaign.dailyLimit ? { enabled: true, limitRub: campaign.dailyLimit.limitRub, carryOver: campaign.dailyLimit.carryOver } : { enabled: false, limitRub: null, carryOver: false };
    if (limit === 0) return { type: "daily_limit", campaignId: campaign.id, enabled: false, limitRub: 0, carryOver: false, previous: prev };
    return limit >= 1000 && limit <= 1_000_000 ? { type: "daily_limit", campaignId: campaign.id, enabled: true, limitRub: Math.round(limit), carryOver: campaign.dailyLimit?.carryOver ?? false, previous: prev } : null;
  }
  if (op === "remove_nm" || op === "add_nm") return campaign && product ? { type: op, campaignId: campaign.id, nmId: product.nmId } : null;
  if (op === "club_discount") {
    const pct = num(spec.clubPercent);
    return product && pct != null && Number.isInteger(pct) && pct >= 0 && pct <= 30 ? { type: "club_discount", nmId: product.nmId, clubPercent: pct, previousPercent: product.clubDiscount ?? null } : null;
  }
  return null;
}

/** Вопрос про отзывы, акции или поставки: показываем настоящие данные из кабинета, если модель блок не добавила. */
export function ensureInfoBlocks(blocks: ChatBlock[], ownerText: string): ChatBlock[] {
  const t = ownerText.toLowerCase().replace(/ё/g, "е");
  // Владелец дал текст отзыва или просит написать ответ/шаблон: список «без ответа» тут лишний.
  if (/[«"][^»"]{15,}[»"]/.test(ownerText) || /(подготов|напиши|сформулируй|шаблон|составь (текст|ответ))/.test(t)) {
    const rest = blocks.filter((b) => !(b.type === "info" && b.kind === "reviews"));
    if (rest.length !== blocks.length || /(отзыв|вопрос[а-я]* покупател)/.test(t)) return rest;
  }
  if (blocks.some((b) => b.type === "info")) return blocks;
  if (/(постав[ьи]|созда|добав|составь|удали|ответь|ответить|напиши|измени|поменя|помоги|подскажи как|сформулируй|как ответить|шаблон)/.test(t)) return blocks;
  const kind = /(отзыв|вопрос[а-я]* покупател|без ответа|негатив)/.test(t) ? "reviews" : /(акци[яиюей]|скидочн[а-я]+ календар)/.test(t) ? "promos" : /(поставк|сборочн|заказы на сборк|fbs|задани[яй] на сборк)/.test(t) ? "supplies" : null;
  if (!kind) return blocks;
  return [{ type: "info", kind } as ChatBlock, ...blocks.filter((b) => b.type !== "article" && b.type !== "section")].slice(0, 2);
}

/** Варианты быстрых ответов от модели: по списку на вопрос, 2–4 коротких непустых строки без повторов. */
export function cleanOptions(raw: unknown, count: number): string[][] | undefined {
  if (!Array.isArray(raw)) return undefined;
  const out = Array.from({ length: count }, (_, i) => {
    const list = Array.isArray(raw[i]) ? (raw[i] as unknown[]) : [];
    const clean = list.filter((o): o is string => typeof o === "string").map((o) => o.trim().replace(/[?]+$/, "")).filter((o) => o.length >= 1 && o.length <= 28);
    const uniq = [...new Set(clean)].slice(0, 4);
    return uniq.length >= 2 ? uniq : [];
  });
  return out.some((l) => l.length > 0) ? out : undefined;
}

/** Проверка фактов в общем ответе (без блоков данных и поиска): определения, расшифровки, формулы, правила Wildberries. */
export const CHAT_FACT_CHECK_SYSTEM = `Ты редактор фактов для ИИ-менеджера продавца Wildberries. Тебе дан вопрос владельца и черновик ответа. Проверь только фактические утверждения: определения терминов, расшифровки аббревиатур, формулы, правила и порядки работы Wildberries и маркетплейсов, налоги и законы. Утверждения о самом приложении (разделы, кнопки, что где делается) не проверяй и не ослабляй: они описаны в поле app_facts и верны.
${TERM_GLOSSARY}
Правила:
- Числа и факты о магазине владельца (цены, остатки, заказы, реклама) не меняй: они взяты из данных.
- Если всё верно или неточности только стилистические, верни {"ok":true}.
- Если есть ошибка или сомнительное утверждение, которое нельзя подтвердить, верни {"ok":false,"fixed":"исправленный ответ целиком, в том же стиле и форматировании","issues":["что было неверно"]}. В исправленном тексте неподтверждаемое утверждение замени честной оговоркой или убери, ничего не выдумывай.
- Не сокращай ответ без нужды и не добавляй новых утверждений.
ФОРМАТ. Только JSON без текста вокруг.`;

/** Кампания из слов владельца: по дате или названию; одна кампания в кабинете подходит без уточнения. null — не определилась однозначно. */
export function pickCampaign(ownerText: string, campaigns: ChatCampaign[]): ChatCampaign | null {
  const t = ownerText.toLowerCase();
  const dates = t.match(/\d{1,2}\.\d{1,2}\.\d{2,4}/g) ?? [];
  if (dates.length > 0) {
    const hit = campaigns.filter((c) => dates.some((d) => c.name.toLowerCase().includes(d)));
    if (hit.length === 1) return hit[0]!;
    return null;
  }
  const named = campaigns.filter((c) => c.name.length >= 4 && t.includes(c.name.toLowerCase()));
  if (named.length === 1) return named[0]!;
  return campaigns.length === 1 ? campaigns[0]! : null;
}

/**
 * Простые команды по кампании («поставь на паузу», «запусти», «пополни на 1000», «лимит расхода 2000») собираются без участия модели:
 * кампанию определяем по дате или названию, число берём из слов. Так команда не теряется, даже если модель ответила аналитикой.
 */
export function ensureCampaignActions(blocks: ChatBlock[], ownerText: string, campaigns: ChatCampaign[]): ChatBlock[] {
  if (blocks.some((b) => b.type === "action") || campaigns.length === 0) return blocks;
  const t = ownerText.toLowerCase().replace(/ё/g, "е");
  if (!/(кампани|реклам)/.test(t)) return blocks;
  const op = /(пауз|останови|выключи|отключи|приостанови)/.test(t) ? "pause" : /(запусти|включи|возобнови|разблокир)/.test(t) ? "resume" : /пополни/.test(t) ? "deposit" : /лимит/.test(t) ? "daily_limit" : null;
  if (!op) return blocks;
  const campaign = pickCampaign(ownerText, campaigns);
  if (!campaign) return blocks;
  const money = t.replace(/\d{1,2}\.\d{1,2}\.\d{2,4}/g, " ").match(/(\d[\d\s]{2,8})\s*(?:₽|руб|р\b)?/);
  const sum = money ? Number(money[1]!.replace(/\s/g, "")) : null;
  const action = buildChatAction({ op, campaignId: campaign.id, sumRub: sum, limitRub: sum }, { products: [], campaigns });
  if (!action) return blocks;
  return [{ type: "action", action } as ChatBlock, ...blocks.filter((b) => b.type !== "analytics" && b.type !== "article" && b.type !== "section")].slice(0, 2);
}

/** Ответ к плану: одна короткая фраза. Сам план показывается только карточкой «Задач», поэтому описание шагов, заголовки и списки из текста убираем. */
export function planLead(text: string): string {
  const first = leadText(text).split(/\n\s*\n/)[0]!.trim();
  const noHeading = first.split(/\n/).filter((l) => !/^\s*(план|шаги|что мешает|день \d)/i.test(l)).join(" ").trim();
  const t = noHeading || first;
  return t.length > 420 ? `${t.slice(0, 420).replace(/\s+\S*$/, "")}…` : t;
}

/** Вопрос про правила, требования и устройство Wildberries: рядом с ответом уместна статья нашей базы знаний. */
export function asksWbRules(text: string): boolean {
  return /(правил|требовани|как работает|как считает|как устроен|что такое|что значит|объясни|комисси|штраф|регламент|упаков|маркиров|возврат|выкуп|карточк[а-я]* товар|инструкц|справк|как подключ|как настро|как созда|как заполн|как загруз|как оформ)/.test(text.toLowerCase());
}

/**
 * Вопрос «какую кампанию?» всегда получает настоящие кампании магазина как быстрые ответы (модель иногда подставляет названия товаров).
 * Одинаковые названия различаются номером; ответ короткий, до 28 знаков.
 */
export function campaignOptions(questions: string[], options: string[][] | undefined, campaigns: Array<{ id: string; name: string }>): string[][] | undefined {
  const asksWhich = (q: string) => /(какую|какой|какая|какие)[^?]{0,50}кампани/i.test(q);
  if (campaigns.length === 0 || !questions.some(asksWhich)) return options;
  const names = campaigns.map((c) => (c.name || `Кампания ${c.id}`).trim());
  const label = (c: { id: string }, n: string) => {
    const dup = names.filter((x) => x === n).length > 1;
    const base = dup ? `${n} №${c.id.slice(-4)}` : n;
    return base.length > 28 ? `${base.slice(0, 27).trimEnd()}…` : base;
  };
  const list = campaigns.slice(0, 5).map((c, i) => label(c, names[i]!));
  return questions.map((q, i) => (asksWhich(q) ? list : options?.[i] ?? []));
}
